    this.polygon(Array.from({ length: 21 }, (_, i) => [(ix + Math.cos(i / 20 * Math.PI) * 0.08) * H, (HORIZON - Math.sin(i / 20 * Math.PI) * 0.025) * H]), this.paint([0.2, 0.35, 0.22]));
