  storm = makeStorm();
  nearTop = new Float32Array(0);
  cows = [];
  chickens = [];
  pigs = [];
  farmer = { x: 0.5, dir: 1, wave: -1, next: 20, g: gait() };
  tractor = { x: -9, dir: 1, next: 14, wheel: 0 };
  smoke = [];
  fireflies = [];
