    const c = e.cow;
    if (!c)
      return;
    if (e.t < 0) {
      this.drawCow(c);
      return;
    }
    const t = e.t;
    const arrive = smoothstep(0, 10, t);
    const leave = smoothstep(26, 36, t) ** 2;
    const ux = lerp(lerp(A + 0.3, c.x, arrive), -0.4, leave);
    const uy = lerp(lerp(0.1, c.y - 0.4, arrive), -0.2, leave) + Math.sin(this.time * 1.5) * 0.005;
