function lerpRGB(a, b, t) {
  return [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)];
}
function lightenGrass(hdr, W, H, pasture, gusts) {
  for (let k = 0;k < pasture.length; k++) {
    const p = pasture[k];
    const x = p % W;
    const g = gusts[x];
    if (g < 0.01)
      continue;
    const y = (p - x) / W;
    const m = 1 + 0.1 * g * (0.4 + 0.6 * Math.sin((x - y * 1.4) / H * 55) ** 2);
    hdr[p * 3] *= m;
    hdr[p * 3 + 1] *= m;
    hdr[p * 3 + 2] *= m;
  }
}
