// wallpapers/flowerbox.ts
var TIME_SCALE6 = 0.35;
var N2 = 14;
var G = N2 + 3;
var CAMERA = 5;
var SS = 2;
var CUBE = 0;
var BALLS = 1;
var STAR = 2;
var PILLOW = 3;
