      fingers.push(cap(fx - size * 0.2 + i * size * 0.16, top - size * 0.02, fx - size * 0.18 + i * size * 0.16, top + size * 0.18, Math.max(size * 0.05, 0.5), Math.max(size * 0.04, 0.45), skin));
