    this.drawShafts();
    this.drawFalls();
    const mist = this.look.mist[1];
    driftMist(this.hdr, this.W, this.H, this.mist, mist[0], mist[1], mist[2], this.rainy ? 0.3 : 0.22);
    this.touch(0, Math.floor(0.5 * this.H), this.W - 1, Math.ceil(0.96 * this.H));
