      ...[-2.25, -2.6, -1.9].map((angle, i) => ({ x: A + 0.03, y: 1.06, angle, length: [0.4, 0.34, 0.3][i], phase: i * 2.3 + 1 })),
      ...[0.6, 0.95].map((angle, i) => ({ x: -0.02, y: -0.04, angle, length: [0.3, 0.26][i], phase: i * 1.3 + 2 })),
