    const hang = (u0, v0, u, v) => [u0 + (u - u0) * Math.cos(trail) - (v - v0) * Math.sin(trail), v0 + (u - u0) * Math.sin(trail) + (v - v0) * Math.cos(trail)];
    const fur = this.paint([0.3, 0.2, 0.12]);
