    const py = w.y * H + Math.sin(t * 0.3) * H * 0.01;
    const face = w.dir;
    const fog2 = this.fogAt(py);
    const x0 = Math.max(0, Math.floor(px - L * 0.65));
    const x1 = Math.min(W - 1, Math.ceil(px + L * 0.65));
