      const ray = RAYS_A2[(x + y * 0.42 + t * 7 | 0) & 1023] * (0.45 + 0.55 * RAYS_B2[(x * 0.7 + y * 0.6 - t * 4.3 | 0) & 1023]) * rayFade[y];
