      const tt = s / segs;
      const sway2 = (Math.sin(t * 0.9 + k.phase + tt * 2.4) * 0.04 + Math.sin(t * 0.37 + k.phase * 2 + tt) * 0.025 + Math.sin(t * 1.7 + tt * 6) * 0.006) * Math.pow(tt, 1.3);
