// wallpapers/pipes.ts
var TIME_SCALE15 = 0.35;
var GY = 8;
var GZ = 12;
var GXM = 40;
var Z0 = 5;
var FOCAL = 0.5 * Z0 / (GY * 0.45);
var PIPE = 0.15;
var BALL = 0.23;
var BEND = 0.5;
var SS2 = 2;
var BLOCK2 = 8;
var BAKE_FRAMES = 45;
var FULL = 0.45;
var FADE4 = 1;
var DX2 = [1, -1, 0, 0, 0, 0];
var DY2 = [0, 0, 1, -1, 0, 0];
var DZ = [0, 0, 0, 0, 1, -1];
var CYL = 0;
var BALLS2 = 1;
var ARC = 2;
