    this.speed = { calm: 0.2, lively: 0.375, teeming: 0.7 }[this.activity];
    this.count = { calm: 1, lively: 3, teeming: 6 }[this.activity];
    this.bends = { calm: 0, lively: 0.1, teeming: 0.35 }[this.activity];
