    this.time += dt;
    this.stepGloom(dt);
    if (!this.grown)
      return;
    this.egg -= dt;
    if (this.egg <= 0 && !this.teapot)
      this.teapot = true;
    if (this.fade >= 0) {
      this.fade += dt / FADE4;
      if (this.fade >= 1)
        this.clear();
      return;
    }
    this.cycle += dt;
    this.burst = Math.max(0, this.burst - dt);
    this.grow(dt * (1 - 0.9 * this.gloom) * (1 + 4 * smoothstep(0, 1, this.burst)));
