      this.launch = this.launch + dt > LAUNCH2 ? -1 : this.launch + dt;
    if (this.landing >= 0)
      this.landing = this.landing + dt > LANDING2 ? -1 : this.landing + dt;
    if (this.flyover >= 0)
      this.flyover = this.flyover + dt > FLYOVER ? -1 : this.flyover + dt;
